{"command":"create","file_text":"/**
 * Privacy redaction helpers shared by the customer erasure workflow.
 *
 * These functions are pure so they can be unit tested without a database. They
 * remove personal data from snapshots while preserving the financial facts and
 * the stable internal identifiers (uuids) that retained records need to stay
 * reconcilable after a customer is deleted.
 */

const REDACTED_NAME = 'Erased Customer';

/** Builds the unique, non-identifying email used to replace a deleted customer's email. */
export function redactedEmailFor(customerId: string): string {
  return `erased+${customerId}@redacted.invalid`;
}

/** Builds the unique, non-identifying external reference for a deleted customer. */
export function redactedExternalReferenceFor(customerId: string): string {
  return `erased:${customerId}`;
}

export const REDACTED_CUSTOMER_NAME = REDACTED_NAME;
export const REDACTED_DESTINATION = 'redacted';

/** Personal fields that must be stripped from retained customer snapshots. */
const PERSONAL_SNAPSHOT_FIELDS = ['email', 'name', 'phone', 'external_reference'] as const;

type Snapshot = Record<string, unknown>;

function isObject(value: unknown): value is Snapshot {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Removes personal data from a customer snapshot while keeping the stable
 * internal identifier (`id`) and any financial/status fields. Returns the
 * redacted snapshot, or `null` when the input is not an object.
 */
export function redactCustomerSnapshot(snapshot: unknown): Snapshot | null {
  if (!isObject(snapshot)) return null;
  const redacted: Snapshot = { ...snapshot };
  for (const field of PERSONAL_SNAPSHOT_FIELDS) {
    if (field in redacted) redacted[field] = null;
  }
  return redacted;
}

/**
 * Collects the unique contact destinations (emails/phone numbers) that must be
 * purged from external delivery systems for a deleted customer. Empty and
 * already-redacted values are ignored so retries converge without sending
 * redacted placeholders.
 */
export function collectDestinations(values: Iterable<string | null | undefined>): string[] {
  const seen = new Set<string>();
  for (const value of values) {
    if (!value) continue;
    if (value === REDACTED_DESTINATION) continue;
    if (value.endsWith('@redacted.invalid')) continue;
    seen.add(value);
  }
  return [...seen];
}","path":"/workspace/source/packages/customers/src/erasure-redaction.ts"}

