{"command":"create","file_text":"import type pg from 'pg';
import { v4 as uuid } from 'uuid';
import { pool } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  last_error: string | null;
  idempotency_key: string;
  completed_at: Date | null;
  created_at: Date;
  updated_at: Date;
}

export interface ErasureRequestView {
  id: string;
  customerId: string;
  status: ErasureStatus;
  attempts: number;
  createdAt: Date;
  updatedAt: Date;
  completedAt: Date | null;
  lastError: string | null;
}

export function toView(row: ErasureRequestRow): ErasureRequestView {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    completedAt: row.completed_at,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  /** Finds an erasure request previously saved for a given idempotency key. */
  async findByIdempotencyKey(
    client: pg.PoolClient,
    merchantId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND idempotency_key=$2 FOR UPDATE`,
      [merchantId, idempotencyKey],
    );
    return result.rows[0];
  }

  /** Finds the single erasure request, if any, already opened for a customer. */
  async findByCustomer(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async create(
    client: pg.PoolClient,
    input: { merchantId: string; customerId: string; idempotencyKey: string },
  ): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
       VALUES($1,$2,$3) RETURNING *`,
      [input.merchantId, input.customerId, input.idempotencyKey],
    );
    return result.rows[0]!;
  }

  /** Enqueues an idempotent cleanup job for an erasure request, if no runnable one exists yet. */
  async enqueueCleanup(
    client: pg.PoolClient,
    requestId: string,
    merchantId: string,
    customerId: string,
  ): Promise<void> {
    await client.query(
      `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload)
       SELECT 'erasure','customer_erasure',$3,$4
       WHERE NOT EXISTS (
         SELECT 1 FROM operations.jobs
         WHERE queue='erasure' AND status IN ('pending','processing','retry')
           AND (payload->>'requestId')=$1
       )`,
      [requestId, undefined, merchantId, { requestId, customerId, merchantId }],
    );
  }
}","path":"/workspace/source/apps/customer-service/src/erasure-repository.ts"}

{"command":"create","file_text":"import { v4 as uuid } from 'uuid';
import { transaction } from '../../../packages/database/src/pool.js';
import { ErasureRepository, type ErasureRequestRow, type ErasureRequestView, toView } from './erasure-repository.js';

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  /**
   * Creates (or resumes) a data deletion request for a customer.
   *
   * Idempotency rules from the privacy API:
   * - Reusing an idempotency key for the same customer returns the same request.
   * - Reusing it for a different customer returns 409 Conflict.
   * - A new key for a customer that already has a request returns that request.
   * - 404 when the customer does not exist or belongs to another merchant.
   */
  async request(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestView> {
    return await transaction(async (client) => {
      const byKey = await this.repository.findByIdempotencyKey(client, merchantId, idempotencyKey);
      if (byKey) {
        if (byKey.customer_id !== customerId) {
          throw Object.assign(new Error('idempotency_key_reused_for_different_customer'), { statusCode: 409 });
        }
        return toView(byKey);
      }

      const exists = await client.query<{ status: string }>(
        `SELECT status FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      if (!exists.rows[0]) {
        throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
      }

      const byCustomer = await this.repository.findByCustomer(client, merchantId, customerId);
      if (byCustomer) {
        await this.maybeResume(client, byCustomer);
        return toView(byCustomer);
      }

      const created = await this.repository.create(client, { merchantId, customerId, idempotencyKey });
      await this.repository.enqueueCleanup(client, created.id, merchantId, customerId);
      return toView(created);
    });
  }

  /** Re-enqueues cleanup for an unfinished request so reposting resumes the workflow. */
  private async maybeResume(
    client: Parameters<Parameters<ErasureService['request']>[1] extends never ? never : Awaited<ReturnType<typeof transaction>>>[0],
    request: ErasureRequestRow,
  ): Promise<void> {
    if (request.status === 'pending' || request.status === 'failed') {
      await this.repository.enqueueCleanup(client, request.id, request.merchant_id, request.customer_id);
    }
  }

  async get(merchantId: string, requestId: string): Promise<ErasureRequestView | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    return row ? toView(row) : undefined;
  }
}

// Re-export the view types so route handlers can reference them concisely.
export type { ErasureRequestView };","path":"/workspace/source/apps/customer-service/src/erasure-service.ts"}

