{"command":"create","file_text":"import type pg from 'pg';
import { pool, transaction } from '../../../packages/database/src/pool.js';

export interface ErasureJobPayload {
  requestId: string;
  customerId: string;
  merchantId: string;
}

export interface Destinations {
  emails: string[];
  paymentIds: string[];
  invoiceIds: string[];
  manifestObjectKeys: { objectKey: string; documentType: string }[];
}

/**
 * Database operations for the customer erasure workflow. Every method is
 * idempotent so a request can be safely retried after a crash or restart and
 * converge on the same result without duplicating destructive work.
 */
export class ErasureCleanupRepository {
  /** Marks a request as actively processing and records an attempt. */
  async markProcessing(requestId: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='processing',attempts=attempts+1,updated_at=now()
       WHERE id=$1 AND status IN ('pending','failed','processing')`,
      [requestId],
    );
  }

  async markCompleted(requestId: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(requestId: string, errorCode: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed',last_error=$2,updated_at=now() WHERE id=$1 AND status='processing'`,
      [requestId, errorCode],
    );
  }

  /** Collects identifiers needed to purge external systems, before DB redaction. */
  async collectDestinations(client: pg.PoolClient, merchantId: string, customerId: string): Promise<Destinations> {
    const customer = await client.query<{ email: string }>(
      `SELECT email FROM customers.customers WHERE merchant_id=$1 AND id=$2`, [merchantId, customerId],
    );
    const contacts = await client.query<{ value: string }>(
      `SELECT value FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    const deliveries = await client.query<{ destination: string }>(
      `SELECT destination FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    const notifications = await client.query<{ destination: string }>(
      `SELECT destination FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    const payments = await client.query<{ id: string }>(
      `SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    const invoices = await client.query<{ id: string }>(
      `SELECT id FROM payments.invoices WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    const manifests = await client.query<{ object_key: string; document_type: string }>(
      `SELECT object_key,document_type FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2 AND document_type IN ('receipt','invoice')`,
      [merchantId, customerId],
    );
    return {
      emails: [
        customer.rows[0]?.email,
        ...contacts.rows.map((row) => row.value),
        ...deliveries.rows.map((row) => row.destination),
        ...notifications.rows.map((row) => row.destination),
      ].filter((value): value is string => Boolean(value)),
      paymentIds: payments.rows.map((row) => row.id),
      invoiceIds: invoices.rows.map((row) => row.id),
      manifestObjectKeys: manifests.rows.map((row) => ({ objectKey: row.object_key, documentType: row.document_type })),
    };
  }

  /**
   * Performs every database redaction and deletion for a customer inside one
   * transaction. Financial records are retained but de-identified; personal
   * records are removed. Re-running this is a no-op.
   */
  async redactDatabase(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
