import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { collectDestinations, redactCustomerSnapshot } from '../../../packages/contracts/src/erasure.js';
import { ErasureCleanupRepository, type Destinations } from './repository.js';

/** Deletes the customer's projection from the search index (idempotent). */
export async function redactOpenSearch(merchantId: string, customerId: string): Promise<void> {
  try {
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: false });
  } catch (error) {
    // A missing document is the desired end state; tolerate not-found.
    const status = (error as { statusCode?: number }).statusCode;
    if (status !== 404) throw error;
  }
}

/** Deletes the customer's cached projections from Redis (idempotent). */
export async function redactRedis(merchantId: string, customerId: string): Promise<void> {
  const redis = new Redis(config().REDIS_URL);
  try {
    const base = `merchant:${merchantId}:customer:${customerId}`;
    await redis.del(base, `${base}:activity`);
  } finally {
    await redis.quit();
  }
}

/** Removes captured email messages addressed to the deleted customer (idempotent). */
export async function redactMailpit(destinations: string[]): Promise<void> {
  const { deleteMailpitMessagesForRecipient } = await import('../../../packages/notifications/src/mailpit.js');
  const unique = collectDestinations(destinations);
  for (const destination of unique) {
    await deleteMailpitMessagesForRecipient(destination);
  }
}

interface StoredDocument {
  customer?: unknown;
  customerSnapshot?: unknown;
  [key: string]: unknown;
}

/**
 * Redacts retained financial documents (receipts, invoices) in object storage
 * in place: the object is kept for financial history but stripped of personal
 * data, and the manifest checksum is updated to match. Idempotent.
 */
export async function redactStoredDocuments(destinations: Destinations): Promise<void> {
  const repository = new ErasureCleanupRepository();
  for (const manifest of destinations.manifestObjectKeys) {
    await redactOneObject(manifest.objectKey, manifest.documentType, repository);
  }
}

async function redactOneObject(objectKey: string, documentType: string, repository: ErasureCleanupRepository): Promise<void> {
  let body: Buffer;
  try {
    const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
    const chunks: Buffer[] = [];
    await new Promise<void>((resolve, reject) => {
      stream.on('data', (chunk: Buffer) => chunks.push(chunk));
      stream.on('error', reject);
      stream.on('end', () => resolve());
    });
    body = Buffer.concat(chunks);
  } catch {
    // Object already removed or unavailable; nothing to redact.
    return;
  }

  const parsed = JSON.parse(body.toString('utf8')) as StoredDocument;
  let changed = false;
  if ('customer' in parsed && parsed.customer !== undefined) {
    parsed.customer = redactCustomerSnapshot(parsed.customer);
    changed = true;
  }
  if ('customerSnapshot' in parsed && parsed.customerSnapshot !== undefined) {
    parsed.customerSnapshot = redactCustomerSnapshot(parsed.customerSnapshot);
    changed = true;
  }
  // Mark the retained document so its de-identified state is auditable.
  parsed.erased = true;
  void documentType;
  const redacted = JSON.stringify(parsed);
  if (changed || redacted !== body.toString('utf8')) {
    await objectStore.putObject(DOCUMENT_BUCKET, objectKey, redacted, Buffer.byteLength(redacted), { 'Content-Type': 'application/json' });
    await repository.updateManifestChecksum(objectKey, createHash('sha256').update(redacted).digest('hex'));
  }
}","path":"/workspace/source/apps/erasure-worker/src/external-cleanup.ts"}

{"command":"create","file_text":"import { logger } from '../../../packages/observability/src/logger.js';
import { redactOpenSearch, redactRedis, redactMailpit, redactStoredDocuments } from './external-cleanup.js';
import { ErasureCleanupRepository, readDestinations, runDatabaseRedaction, type ErasureJobPayload } from './repository.js';

/**
 * Runs every cleanup step for one erasure request. Each step is idempotent, so
 * a retried request converges on the same result. The request is only marked
 * `completed` once personal data is gone from active systems and no delayed
 * processing can restore it (the erased customer cannot be written to, and
 * replayed events are de-duplicated by consumers).
 */
export async function processErasure(payload: ErasureJobPayload): Promise<void> {
  const { requestId, merchantId, customerId } = payload;
  const repository = new ErasureCleanupRepository();

  await repository.markProcessing(requestId);
  try {
    const destinations = await readDestinations(merchantId, customerId);
    await redactMailpit(destinations.emails);
    await redactOpenSearch(merchantId, customerId);
    await redactRedis(merchantId, customerId);
    await redactStoredDocuments(destinations);
    await runDatabaseRedaction(merchantId, customerId);
    await repository.markCompleted(requestId);
  } catch (error) {
    const code = error instanceof Error ? error.message.slice(0, 80) : 'erasure_failed';
    logger.error({ error, requestId, customerId }, 'erasure request failed');
    await repository.markFailed(requestId, code);
    throw error;
  }
}","path":"/workspace/source/apps/erasure-worker/src/processor.ts"}

{"command":"create","file_text":"import { randomUUID } from 'node:crypto';
import { config } from '../../packages/config/src/index.js';
import { logger } from '../../packages/observability/src/logger.js';
import {
  claimJob,
  completeJob,
  failJob,
  recoverExpiredJobLeases,
  type ClaimedJob,
} from '../../packages/operations/src/job-lifecycle.js';
import { transaction } from '../../packages/database/src/pool.js';
import { processErasure } from './processor.js';
import type { ErasureJobPayload } from './repository.js';

process.env.SERVICE_NAME = 'erasure-worker';
void config();
const workerId = `erasure-worker-${randomUUID()}`;
const controller = new AbortController();

async function handle(job: ClaimedJob<ErasureJobPayload>): Promise<void> {
  await processErasure(job.payload);
  await transaction(async (client) => await completeJob(client, job));
}

async function run(signal: AbortSignal): Promise<void> {
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await recoverExpiredJobLeases('erasure');
      lastLeaseRecovery = Date.now();
    }
    const job = await claimJob<ErasureJobPayload>('erasure', workerId);
    if (!job) {
      await new Promise((resolve) => setTimeout(resolve, 250));
      continue;
    }
    try {
      await handle(job);
    } catch (error) {
      logger.error({ error, jobId: job.id }, 'erasure job failed');
      await transaction(async (client) => await failJob(client, job, error));
    }
  }
}

void run(controller.signal);
logger.info({ workerId }, 'erasure worker started');
for (const signal of ['SIGTERM', 'SIGINT'] as const) process.on(signal, () => controller.abort());","path":"/workspace/source/apps/erasure-worker/src/main.ts"}

