{"command":"create","file_text":"import assert from 'node:assert/strict';
import test from 'node:test';
import { randomUUID } from 'node:crypto';
import {
  collectDestinations,
  redactedEmailFor,
  redactedExternalReferenceFor,
  redactCustomerSnapshot,
} from '../packages/contracts/src/erasure.js';

test('customer snapshot redaction keeps the internal id and removes personal fields', () => {
  const id = randomUUID();
  const snapshot = {
    id, email: 'ada@example.test', name: 'Ada Lovelace', phone: '+1-415-555-0101',
    external_reference: 'crm-ada-001', status: 'active', metadata: { segment: 'enterprise' },
  };
  const redacted = redactCustomerSnapshot(snapshot);
  assert.equal(redacted?.id, id);
  assert.equal(redacted?.status, 'active');
  assert.equal(redacted?.email, null);
  assert.equal(redacted?.name, null);
  assert.equal(redacted?.phone, null);
  assert.equal(redacted?.external_reference, null);
});

test('customer snapshot redaction is idempotent and tolerates non-object payloads', () => {
  const redacted = redactCustomerSnapshot({ id: 'x', email: 'a@b.test' });
  assert.deepEqual(redactCustomerSnapshot(redacted), { id: 'x', email: null });
  assert.equal(redactCustomerSnapshot(null), null);
  assert.equal(redactCustomerSnapshot('string'), null);
});

test('redacted identifiers are unique per customer and non-identifying', () => {
  const id = randomUUID();
  assert.equal(redactedEmailFor(id), `erased+${id}@redacted.invalid`);
  assert.equal(redactedExternalReferenceFor(id), `erased:${id}`);
  assert.notEqual(redactedEmailFor(id), redactedEmailFor(randomUUID()));
});

test('destination collection deduplicates and skips already-redacted values for safe retries', () => {
