const MERCHANT_ID = '10000000-0000-4000-8000-000000000001';
const erasureService = new ErasureService();

async function createCustomer(email: string, name: string): Promise<string> {
  return await transaction(async (client) => {
    const result = await client.query<{ id: string }>(
      `INSERT INTO customers.customers(merchant_id,external_reference,email,name,phone,metadata)
       VALUES($1,$2,$3,$4,$5,$6) RETURNING id`,
      [MERCHANT_ID, `ext-${randomUUID()}`, email, name, '+1-555-555-0101', { segment: 'retail' }],
    );
    const customerId = result.rows[0]!.id;
    await client.query(
      `INSERT INTO customers.addresses(merchant_id,customer_id,kind,line1,city,postal_code,country)
       VALUES($1,$2,'billing','123 Market St','SF','94105','US')`,
      [MERCHANT_ID, customerId],
    );
    await client.query(
      `INSERT INTO customers.contacts(merchant_id,customer_id,kind,value,is_primary)
       VALUES($1,$2,'email',$3,true)`,
      [MERCHANT_ID, customerId, email],
    );
    await client.query(
      `INSERT INTO customers.payment_method_refs(merchant_id,customer_id,provider_token,type,brand,last4,billing_name)
       VALUES($1,$2,$3,'card','visa','4242','Test Person')`,
      [MERCHANT_ID, customerId, `tok_${randomUUID()}`],
    );
    const snapshot = { id: customerId, email, name, phone: '+1-555-555-0101', external_reference: 'ext', status: 'active' };
    const payment = await client.query<{ id: string }>(
      `INSERT INTO payments.payment_intents(merchant_id,customer_id,payment_method_id,amount,currency,status,description,customer_snapshot)
       VALUES($1,$2,$3,2500,'USD','succeeded','Order for ${name}',$4) RETURNING id`,
      [MERCHANT_ID, customerId, randomUUID(), snapshot],
    );
    await client.query(
      `INSERT INTO payments.refunds(merchant_id,payment_intent_id,amount,reason,status,customer_email)
       VALUES($1,$2,500,'customer requested','succeeded',$3)`,
      [MERCHANT_ID, payment.rows[0]!.id, email],
    );
    await client.query(
      `INSERT INTO operations.email_deliveries(merchant_id,customer_id,destination,template,subject,text_body,html_body)
       VALUES($1,$2,$3,'payment-receipt','Subject','body text','<p>body</p>')`,
      [MERCHANT_ID, customerId, email],
    );
    await client.query(
      `INSERT INTO operations.notifications(merchant_id,customer_id,channel,destination,template,payload,status)
       VALUES($1,$2,'email',$3,'payment-receipt',$4,'delivered')`,
      [MERCHANT_ID, customerId, email, { customerEmail: email }],
    );
    await client.query(
      `INSERT INTO operations.analytics_events(merchant_id,customer_id,event_type,email,properties,occurred_at)
       VALUES($1,$2,'payment.succeeded',$3,$4,now())`,
      [MERCHANT_ID, customerId, email, { customerEmail: email }],
    );
    return customerId;
  });
}

async function assertRedacted(label: string, customerId: string): Promise<void> {
  const customer = await pool.query<{ email: string; name: string; phone: string | null; status: string; external_reference: string; metadata: Record<string, string> }>(
    `SELECT email,name,phone,status,external_reference,metadata FROM customers.customers WHERE id=$1`, [customerId],
  );
  const row = customer.rows[0]!;
  console.log(JSON.stringify({ label, customer: row }));
  if (row.status !== 'erased') throw new Error(`${label}: customer not erased`);
  if (row.email !== `erased+${customerId}@redacted.invalid`) throw new Error(`${label}: email not redacted`);
  if (row.name !== 'Erased Customer') throw new Error(`${label}: name not redacted`);
  if (row.phone !== null) throw new Error(`${label}: phone not redacted`);

  const addresses = await pool.query(`SELECT count(*)::int c FROM customers.addresses WHERE customer_id=$1`, [customerId]);
  if (addresses.rows[0]!.c !== 0) throw new Error(`${label}: addresses remain`);
  const contacts = await pool.query(`SELECT count(*)::int c FROM customers.contacts WHERE customer_id=$1`, [customerId]);
  if (contacts.rows[0]!.c !== 0) throw new Error(`${label}: contacts remain`);
  const methods = await pool.query(`SELECT count(*)::int c FROM customers.payment_method_refs WHERE customer_id=$1`, [customerId]);
  if (methods.rows[0]!.c !== 0) throw new Error(`${label}: payment methods remain`);

  const payments = await pool.query<{ customer_snapshot: Record<string, unknown>; description: string | null }>(
    `SELECT customer_snapshot,description FROM payments.payment_intents WHERE customer_id=$1`, [customerId],
  );
  const snap = payments.rows[0]!.customer_snapshot as { email: unknown; name: unknown; phone: unknown; external_reference: unknown };
  if (snap.email !== null || snap.name !== null || snap.phone !== null || snap.external_reference !== null) {
    throw new Error(`${label}: payment snapshot still has PII`);
  }
  if (payments.rows[0]!.description !== null) throw new Error(`${label}: payment description not cleared`);

  const refunds = await pool.query<{ customer_email: string | null }>(
    `SELECT customer_email FROM payments.refunds WHERE payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE customer_id=$1)`, [customerId],
  );
  if (refunds.rows[0]!.customer_email !== null) throw new Error(`${label}: refund email not redacted`);

  const deliveries = await pool.query<{ destination: string }>(
    `SELECT destination FROM operations.email_deliveries WHERE customer_id=$1`, [customerId],
  );
  if (deliveries.rows[0]!.destination !== 'redacted') throw new Error(`${label}: email delivery not redacted`);

  const analytics = await pool.query<{ email: string | null }>(
    `SELECT email FROM operations.analytics_events WHERE customer_id=$1`, [customerId],
  );
  if (analytics.rows[0]!.email !== null) throw new Error(`${label}: analytics email not redacted`);

  const sandbox = await pool.query(`SELECT count(*)::int c FROM provider_sandbox.customers WHERE payflow_customer_id=$1`, [customerId]);
  // sandbox customer not created in this test; tolerate zero.
  console.log(JSON.stringify({ label, sandboxCustomers: sandbox.rows[0]!.c }));
}

console.log('--- creating customer ---');
const customerId = await createCustomer('ada.lovelace@example.test', 'Ada Lovelace');

console.log('--- requesting erasure (first key) ---');
const key1 = `erasure-key-${randomUUID()}`;
const request = await erasureService.request(MERCHANT_ID, customerId, key1);
console.log(JSON.stringify({ request }));
if (request.status !== 'pending') throw new Error('expected pending');
if (request.customerId !== customerId) throw new Error('customer id mismatch');

console.log('--- requesting erasure (same key, same customer) ---');
const replay = await erasureService.request(MERCHANT_ID, customerId, key1);
if (replay.id !== request.id) throw new Error('idempotency replay returned a different request');

console.log('--- requesting erasure (new key, same customer) ---');
const newKey = `erasure-key-${randomUUID()}`;
const existing = await erasureService.request(MERCHANT_ID, customerId, newKey);
if (existing.id !== request.id) throw new Error('new key should return existing request');

console.log('--- 404 for unknown customer ---');
try {
  await erasureService.request(MERCHANT_ID, randomUUID(), `erasure-key-${randomUUID()}`);
  throw new Error('expected 404 for unknown customer');
} catch (error) {
  if ((error as { statusCode?: number }).statusCode !== 404) throw error;
}

console.log('--- 409 for idempotency key reused with different customer ---');
const customerId2 = await createCustomer('grace.hopper@example.test', 'Grace Hopper');
try {
  await erasureService.request(MERCHANT_ID, customerId2, key1);
  throw new Error('expected 409 for reused key');
} catch (error) {
  if ((error as { statusCode?: number }).statusCode !== 409) throw error;
}

console.log('--- destinations before redaction ---');
const destinations = await readDestinations(MERCHANT_ID, customerId);
console.log(JSON.stringify({ destinations: { emails: destinations.emails, payments: destinations.paymentIds } }));

console.log('--- running database redaction ---');
await runDatabaseRedaction(MERCHANT_ID, customerId);
await assertRedacted('after redaction', customerId);

console.log('--- re-running database redaction (idempotency) ---');
await runDatabaseRedaction(MERCHANT_ID, customerId);
await assertRedacted('after re-run', customerId);

console.log('--- verify other customer unaffected ---');
const other = await pool.query<{ email: string; status: string }>(
  `SELECT email,status FROM customers.customers WHERE id=$1`, [customerId2],
);
if (other.rows[0]!.email !== 'grace.hopper@example.test' || other.rows[0]!.status !== 'active') {
  throw new Error('other customer was affected by erasure');
}
console.log(JSON.stringify({ otherCustomer: other.rows[0] }));

console.log('--- GET request ---');
const fetched = await erasureService.get(MERCHANT_ID, request.id);
if (!fetched) throw new Error('could not fetch erasure request');
console.log(JSON.stringify({ fetched }));

console.log('--- GET cross-merchant returns undefined ---');
const OTHER_MERCHANT = '20000000-0000-4000-8000-000000000001';
const cross = await erasureService.get(OTHER_MERCHANT, request.id);
if (cross) throw new Error('cross-merchant access should return undefined');

console.log(JSON.stringify({ status: 'erasure-end-to-end-ok' }));
await pool.end();","path":"/workspace/source/scripts/erasure-smoke.ts"}

