const MERCHANT_ID = '10000000-0000-4000-8000-000000000001';
const RAW_API_KEY = `pf_test_erasure_${randomUUID()}`;
const runSuffix = randomUUID().slice(0, 8);

async function seedApiKey(): Promise<void> {
  await pool.query(
    `INSERT INTO platform.merchants(id,name,default_currency) VALUES($1,'Test','USD') ON CONFLICT(id) DO NOTHING`,
    [MERCHANT_ID],
