      `INSERT INTO customers.customers(merchant_id,external_reference,email,name,phone)
       VALUES($1,$2,$3,$4,$5) RETURNING id`,
      [MERCHANT_ID, `ext-${randomUUID()}`, `${runSuffix}+ada@example.test`, 'Ada Lovelace', '+1-555-555-0001'],
