    return result.rows[0]!.id;
  });
}

const app = Fastify();
registerErrorHandler(app);
await app.register(customerRoutes);
await app.ready();

await seedApiKey();
const customerId = await seedCustomer();
const headers = { authorization: `Bearer ${RAW_API_KEY}` };

console.log('--- POST erasure request ---');
const post1 = await app.inject({ method: 'POST', url: `/v1/customers/${customerId}/erasure-requests`, headers: { ...headers, 'idempotency-key': `erasure-key-${randomUUID()}` } });
console.log({ status: post1.statusCode, body: post1.body });
if (post1.statusCode !== 202) throw new Error(`expected 202, got ${post1.statusCode}`);
const request = post1.json() as { id: string; status: string };
if (request.status !== 'pending') throw new Error('expected pending');

console.log('--- GET erasure request ---');
const get1 = await app.inject({ method: 'GET', url: `/v1/erasure-requests/${request.id}`, headers });
console.log({ status: get1.statusCode, body: get1.body });
if (get1.statusCode !== 200) throw new Error(`expected 200, got ${get1.statusCode}`);

console.log('--- GET unknown erasure request returns 404 ---');
const get404 = await app.inject({ method: 'GET', url: `/v1/erasure-requests/${randomUUID()}`, headers });
if (get404.statusCode !== 404) throw new Error(`expected 404, got ${get404.statusCode}`);

console.log('--- POST for unknown customer returns 404 ---');
const post404 = await app.inject({ method: 'POST', url: `/v1/customers/${randomUUID()}/erasure-requests`, headers: { ...headers, 'idempotency-key': `erasure-key-${randomUUID()}` } });
if (post404.statusCode !== 404) throw new Error(`expected 404, got ${post404.statusCode}`);

console.log('--- POST without idempotency key returns 400 ---');
const post400 = await app.inject({ method: 'POST', url: `/v1/customers/${customerId}/erasure-requests`, headers });
if (post400.statusCode !== 400) throw new Error(`expected 400, got ${post400.statusCode}`);

console.log('--- POST with short idempotency key returns 400 ---');
const postShort = await app.inject({ method: 'POST', url: `/v1/customers/${customerId}/erasure-requests`, headers: { ...headers, 'idempotency-key': 'short' } });
if (postShort.statusCode !== 400) throw new Error(`expected 400, got ${postShort.statusCode}`);

console.log('--- POST without privacy scope returns 403 ---');
const unscopedKey = `pf_test_unscoped_${randomUUID()}`;
await pool.query(
  `INSERT INTO platform.api_keys(merchant_id,key_hash,label,scopes)
   VALUES($1,$2,'unscoped',ARRAY['customers:read']) ON CONFLICT DO NOTHING`,
  [MERCHANT_ID, createHash('sha256').update(unscopedKey).digest('hex')],
);
const post403 = await app.inject({ method: 'POST', url: `/v1/customers/${customerId}/erasure-requests`, headers: { authorization: `Bearer ${unscopedKey}`, 'idempotency-key': `erasure-key-${randomUUID()}` } });
if (post403.statusCode !== 403) throw new Error(`expected 403, got ${post403.statusCode}`);

console.log(JSON.stringify({ status: 'erasure-http-ok' }));
await app.close();
await pool.end();","path":"/workspace/source/scripts/erasure-http-smoke.ts"}

